$smartJs = <<<'JS'
<script id="smart-v2-js">
(function(){
 const form=document.getElementById('leadForm'); if(!form)return;
 const steps=[...document.querySelectorAll('.smartStep')], bars=[...document.querySelectorAll('.smartProgress span')]; let current=0;
 const val=id=>(document.getElementById(id)?.value||'').trim();
 const prices={'Корзина для кондиционера':7500,'Кронштейны':690,'Подставка одноуровневая':2470,'Подставка двухуровневая':5850};
 const money=n=>new Intl.NumberFormat('ru-RU').format(Math.round(n))+' ₽';
 function show(n){current=Math.max(0,Math.min(steps.length-1,n));steps.forEach((s,i)=>s.classList.toggle('active',i===current));bars.forEach((b,i)=>b.classList.toggle('active',i<=current));document.getElementById('form').scrollIntoView({behavior:'smooth',block:'start'});}
 function estimate(){const p=val('product'),q=Math.max(1,parseInt(val('qty')||'1',10)||1),u=prices[p]||0;document.getElementById('sumProduct').textContent=p||'—';document.getElementById('sumQty').textContent=q+' шт.';document.getElementById('sumSize').textContent=val('size')||val('model')||(val('size_mode')==='help'?'подберём по фото':'уточняется');document.getElementById('sumRal').textContent=val('ral')||'уточняется';document.getElementById('sumCity').textContent=val('city')||'уточняется';document.getElementById('estimatePrice').textContent=u?'≈ '+money(u):'По расчёту';document.getElementById('estimateUnitText').textContent=u?'ориентир за 1 ед.':'после проверки задачи';document.getElementById('estimateTotalText').textContent=u?'≈ '+money(u*q):'Уточним';}
 function valid(){if(current===1&&!/^[1-9][0-9]{0,5}$/.test(val('qty'))){alert('Укажите количество от 1 до 999999.');return false}if(current===3&&!val('contact')){alert('Укажите контакт для связи.');return false}if(current===3&&!document.getElementById('consent').checked){alert('Подтвердите согласие на обработку данных.');return false}return true}
 document.querySelectorAll('.smartNext').forEach(b=>b.onclick=()=>{if(valid())show(current+1)});document.querySelectorAll('.smartBack').forEach(b=>b.onclick=()=>show(current-1));
 document.querySelectorAll('.choiceBtn').forEach(b=>b.onclick=()=>{document.querySelectorAll('.choiceBtn').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('size_mode').value=b.dataset.mode;document.querySelectorAll('.conditional').forEach(x=>x.classList.toggle('active',x.dataset.for===b.dataset.mode));estimate()});
 ['product','qty','size','model','ral','city','install'].forEach(id=>document.getElementById(id)?.addEventListener('input',estimate));
 const photos=document.getElementById('photos'),preview=document.getElementById('photoPreview');photos.addEventListener('change',()=>{preview.innerHTML='';[...photos.files].slice(0,5).forEach((f,i)=>{if(!f.type.startsWith('image/'))return;const box=document.createElement('div');box.className='photoThumb';const img=document.createElement('img'),b=document.createElement('b');b.textContent=i+1;box.append(img,b);preview.appendChild(box);const r=new FileReader();r.onload=e=>img.src=e.target.result;r.readAsDataURL(f)})});
 const qs=new URLSearchParams(location.search);document.getElementById('source_url').value=location.href.slice(0,500);document.getElementById('utm_source').value=(qs.get('utm_source')||'').slice(0,100);document.getElementById('utm_campaign').value=(qs.get('utm_campaign')||'').slice(0,150);
 form.addEventListener('submit',async e=>{e.preventDefault();current=3;if(!valid())return;const btn=document.getElementById('serverSend'),status=document.getElementById('formStatus');btn.disabled=true;btn.textContent='Отправляем…';status.textContent='';status.className='formStatus';try{const r=await fetch('/send.php',{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest'}});let out={};try{out=await r.json()}catch(_){ }if(!r.ok||!out.ok)throw new Error(out.message||'Не удалось отправить заявку.');status.textContent='Готово. Заявка отправлена Александру.';status.classList.add('success');document.getElementById('smartSuccess').classList.add('show');document.getElementById('successText').textContent='Номер заявки: '+(out.request_id||'создан')+'. '+(out.photos_sent?'Фото и параметры':'Параметры')+' переданы.'}catch(err){status.textContent=(err.message||'Ошибка отправки')+' Можно открыть Telegram ниже.';status.classList.add('error')}finally{btn.disabled=false;btn.textContent='Отправить фото и получить расчёт →'}});
 estimate();
})();
</script>
JS;

